import{_ as a}from"./chunks/poc-flow.s6rMXeKf.js";import{_ as t,c as r,o,a2 as i}from"./chunks/framework.QTfwLiL8.js";const f=JSON.parse('{"title":"0037 Scaling Advisor","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0037-scaling-advisor","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0037-scaling-advisor/README.md","to":"README.md"},"title":"0037 Scaling Advisor","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0037-scaling-advisor/_index.md","filePath":"docs/proposals/0037-scaling-advisor/_index.md","lastUpdated":null}'),s={name:"docs/proposals/0037-scaling-advisor/_index.md"};function n(l,e,c,d,h,u){return o(),r("div",null,e[0]||(e[0]=[i('<h1 id="gep-0037-scaling-advisor" tabindex="-1">GEP-0037: Scaling Advisor <a class="header-anchor" href="#gep-0037-scaling-advisor" aria-label="Permalink to &quot;GEP-0037: Scaling Advisor&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="/docs/proposals/0037-scaling-advisor/readme/#gep-0037-scaling-advisor">GEP-0037: Scaling Advisor</a><ul><li><a href="/docs/proposals/0037-scaling-advisor/readme/#table-of-contents">Table of Contents</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#summary">Summary</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#motivation">Motivation</a><ul><li><a href="/docs/proposals/0037-scaling-advisor/readme/#issues--challenges">Issues &amp; Challenges</a><ul><li><a href="/docs/proposals/0037-scaling-advisor/readme/#multiple-overlapping-actors">Multiple Overlapping Actors:</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#ca-inherent-design-flaws">CA inherent design flaws</a><ul><li><a href="/docs/proposals/0037-scaling-advisor/readme/#impedence-mismatch-between-ca-and-kube-scheduler">Impedence mismatch between CA and kube-scheduler</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#inefficient-scaling-of-nodegroups">Inefficient scaling of NodeGroup(s)</a></li></ul></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#scalability-challenges">Scalability challenges</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#maintenance-challenges">Maintenance challenges</a><ul><li><a href="/docs/proposals/0037-scaling-advisor/readme/#diagnostic-challenges">Diagnostic challenges</a></li></ul></li></ul></li></ul></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#way-forward">Way forward</a><ul><li><a href="/docs/proposals/0037-scaling-advisor/readme/#alternatives-evaluated">Alternatives evaluated</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#how-we-addressed-ca-challenges">How we addressed CA challenges?</a><ul><li><a href="/docs/proposals/0037-scaling-advisor/readme/#single-actor-responsibility">Single actor responsibility</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#alleviating-ca-inherent-design-flaws">Alleviating CA inherent design flaws</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#scalability">Scalability</a></li></ul></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#proof-of-concept-validation">Proof of concept validation</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#envisaged-value-differentiators">Envisaged value differentiators</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#risk-mitigation">Risk Mitigation</a></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#non-goal">Non Goal</a></li></ul></li><li><a href="/docs/proposals/0037-scaling-advisor/readme/#appendix">Appendix</a></li></ul></li></ul><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Gardener uses a <a href="https://github.com/gardener/autoscaler/tree/machine-controller-manager-provider/cluster-autoscaler" target="_blank" rel="noreferrer">fork</a> of upstream <a href="https://github.com/kubernetes/autoscaler/tree/master/cluster-autoscaler" target="_blank" rel="noreferrer">Cluster-Autoscaler</a> (a.k.a. CA) to scale out/in Shoot clusters and it uses <a href="https://github.com/gardener/machine-controller-manager" target="_blank" rel="noreferrer">machine-controller-manager</a> (a.k.a. MCM) to manage the lifecycle of machines. In the CA fork, we have an in-tree implementation of <a href="https://github.com/gardener/autoscaler/blob/45e190f4bd7890e0029bef8eb9affa0946f135d5/cluster-autoscaler/cloudprovider/cloud_provider.go#L106" target="_blank" rel="noreferrer">CloudProvider</a> interface for <a href="https://github.com/gardener/autoscaler/blob/45e190f4bd7890e0029bef8eb9affa0946f135d5/cluster-autoscaler/cloudprovider/mcm/mcm_cloud_provider.go#L69" target="_blank" rel="noreferrer">MCM</a>. Over several years of using these components together, we have encountered numerous challenges and shortcomings when working with CA.</p><p>This proposal highlights the following:</p><ul><li>Challenges and the shortcomings of current CA and its interplay with MCM.</li><li>The extensive simulation environment that was built during the POC phase, which provides capabilities to capture events from any Gardener cluster and replay the events on a local kubernetes cluster with virtual CA. This helped us capture and understand the current CA&#39;s behavior, identify its shortcomings and compare the CA&#39;s scale-up plan against the scaling advice offered by our alternative system.</li><li>Provides a glimpse of the way forward from here.</li></ul><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Gardener provides capabilities to scale-in and scale-out a kubernetes cluster via <a href="https://github.com/gardener/autoscaler/tree/machine-controller-manager-provider/cluster-autoscaler" target="_blank" rel="noreferrer">Cluster Autoscaler</a>. Consumers can tune a subset of knobs provided out of CA by configuring <a href="https://github.com/gardener/gardener/blob/50828b680ca098ed33f617c5bc60bf1dce393124/pkg/apis/core/v1beta1/types_shoot.go#L599" target="_blank" rel="noreferrer">ClusterAutoscaler configuration</a> as part of the <a href="https://github.com/gardener/gardener/blob/50828b680ca098ed33f617c5bc60bf1dce393124/pkg/apis/core/v1beta1/types_shoot.go#L25" target="_blank" rel="noreferrer">Shoot</a> resource. Based on our experience running Cluster Autoscaler and Machine Controller Manager in production environments across thousands of clusters, we have gathered valuable insights that have prompted us to reevaluate the Cluster Autoscaler component. In this document, we outline some of these observations.</p><h3 id="issues-challenges" tabindex="-1">Issues &amp; Challenges <a class="header-anchor" href="#issues-challenges" aria-label="Permalink to &quot;Issues &amp; Challenges&quot;">​</a></h3><h4 id="multiple-overlapping-actors" tabindex="-1">Multiple Overlapping Actors: <a class="header-anchor" href="#multiple-overlapping-actors" aria-label="Permalink to &quot;Multiple Overlapping Actors:&quot;">​</a></h4><ul><li>Having overlapping responsibilities between CA and MCM causes the following issues: <ul><li>CA and Gardener worker reconciler updates the replicas on <code>MachineDeployment</code> (mapped 1:1 to CA NodeGroup). <a href="https://github.com/gardener/gardener/pull/9925" target="_blank" rel="noreferrer">Gardener Issue</a> reveals the problem of having multiple actors trying to update the <code>MachineDeployment</code> replicas resulting in lost updates.</li><li>CA and MCM have overlapping timeouts: <ul><li><a href="https://github.com/gardener/gardener/blob/d395f33500d91c144202d15b9760e39a3783a973/example/90-shoot.yaml#L136C24-L136C24" target="_blank" rel="noreferrer">machineCreationTimeout</a> and <a href="https://github.com/gardener/gardener/blob/d395f33500d91c144202d15b9760e39a3783a973/example/90-shoot.yaml#L286" target="_blank" rel="noreferrer">maxNodeProvisionTime</a> which if misconfigured can result in preventing CA from backing-off from a NodeGroup. See <em>Live-Issue#6040</em> and the <a href="https://pages.github.tools.sap/kubernetes/gardener/docs/faq/sap-internal/ca-mcm-faqs/#how-to-configure-machinecreationtimeout-and-maxnodeprovisiontime-properly" target="_blank" rel="noreferrer">recommendation</a> on how to correctly set these values.</li><li><a href="https://github.com/gardener/gardener/blob/d395f33500d91c144202d15b9760e39a3783a973/example/90-shoot.yaml#L134" target="_blank" rel="noreferrer">machineDrainTimeout</a> and <a href="https://github.com/gardener/gardener/blob/d395f33500d91c144202d15b9760e39a3783a973/example/90-shoot.yaml#L285" target="_blank" rel="noreferrer">maxGracefulTerminationSeconds</a> is another set of overlapping timeouts. Consumers need to always follow the <a href="https://pages.github.tools.sap/kubernetes/gardener/docs/faq/sap-internal/ca-mcm-faqs/#how-to-configure-machinedraintimeout-and-maxgracefulterminationseconds-properly" target="_blank" rel="noreferrer">recommendation</a> when setting these timeouts.</li></ul></li></ul></li><li>When CA starts or restarts post a crash it will <a href="https://github.com/kubernetes/autoscaler/blob/5cd491a5a18b4b93f742351e3ebb195e358d2ea3/cluster-autoscaler/core/static_autoscaler.go#L239" target="_blank" rel="noreferrer">remove</a> previously added<code>ToBeDeletedByClusterAutoscaler</code> taints on nodes. This blind removal of taints upon restart has caused several issues which occur due to race conditions between MCM and CA. Removal of taints allows kube-scheduler to consider these nodes as target for pod deployment. If MCM is already in the process of handling the node(s) removal request, this can potentially cause downtime for the pods already deployed on those nodes.</li><li>The Cluster Autoscaler (CA) triggers the draining of nodes marked for deletion. However, node draining is already managed by the Machine Controller Manager (MCM) for any node marked for termination. Node draining should be handled exclusively by MCM (as the sole actor), since it is closely linked to node lifecycle management, which is outside the scope of CA’s responsibilities.</li></ul><h4 id="ca-inherent-design-flaws" tabindex="-1">CA inherent design flaws <a class="header-anchor" href="#ca-inherent-design-flaws" aria-label="Permalink to &quot;CA inherent design flaws&quot;">​</a></h4><ul><li>CA starts several go-routines calling methods on Cloud provider implementations, which can potentially lead to race conditions. One such <a href="https://github.com/gardener/autoscaler/pull/341" target="_blank" rel="noreferrer">issue</a> was identified, resulting in duplicate reduction of replicas for a MachineDeployment. This forced the developers to take a <code>sync.Mutex</code> to ensure that not more than one go-routine updates the replicas for a <code>MachineDeployment</code>. Upon reviewing other cloud provider implementations, such as <code>ClusterAPI</code> we found they have also taken similar measures, as seen <a href="https://github.com/kubernetes/autoscaler/blob/78c8173b979316f892327022d53369760b000210/cluster-autoscaler/cloudprovider/clusterapi/clusterapi_nodegroup.go#L105-L106" target="_blank" rel="noreferrer">here</a>. Using <code>sync.Mutex</code> can potentially cause deadlocks if not done right and also can result in a potential delay when running the reconciliation loop.</li><li>CA has become quite complex w.r.t to the number of tunable parameters. As of release <code>v1.32.0</code> there are 113 CLI flags. Out of these 6 CLI flags are specific to cloud providers. This not only makes the usage challenging but due to a lot of in-tree cloud provider implementations it makes the API littered with cloud-provider specific CLI flags. At the time of writing this document, 15 CLI flags have been exposed to be directly set via the Shoot API.</li><li>The current design and complexity of the code base makes it harder to make changes and maintain such changes across releases. See <a href="https://github.com/kubernetes/autoscaler/issues/5394" target="_blank" rel="noreferrer">Issue#5394</a> where it was proposed to split CA into provider agnostic and provider specific parts. It was further proposed to develop it into a pluggable library. This proposal was also discussed in autoscaler SIG group and was eventually rejected due to high maintenance and possibility to introduce regressions.</li><li>CA does not follow kubernetes operator best practices. It does not expose scale-up plan as a consumable resource. It neither uses client-go work queues nor controller-runtime which highlights its age. It is effectively a legacy software component which is difficult to debug.</li><li>It has been observed that CA has several stale fundamental issues. A few examples: <ul><li>CA does not wait for cache syncs before scaling-in nodes identified as underutilized. See <a href="https://github.com/kubernetes/autoscaler/issues/7419" target="_blank" rel="noreferrer">Issue#7419</a>.</li><li>Issues during rolling update: See <a href="https://github.com/kubernetes/autoscaler/issues/5465" target="_blank" rel="noreferrer">Issue#5465</a>.</li><li>CA has issues during scale-in, especially when the pods are configured with TopologySpreadConstraints. See <a href="https://github.com/kubernetes/autoscaler/issues/6984" target="_blank" rel="noreferrer">Issue#6984</a> which got closed due to inactivity.</li></ul></li><li>When CA makes a decision to scale-out a NodeGroup for unschdelued pods it looks at existing nodes. In <em>Live-Issue#5498</em> the customer applied node level taints to achieve tenant isolation. Even though this taint is not applied uniformly across all nodes in the same worker pool, CA gets any existing node and assumes that taints on the node is same across all Nodes in the NodeGroup. If the unscheduled pod does not tolerate this taint then CA will not scale-out this NodeGroup. This is an incorrect assumption and potentially leads to pods remaining unscheduled.</li><li>CA does not disambiguate between scaling plan and applying the plan. CA invokes the cloud provider implementations to apply the scaling plan, leaving no choice to the provider to evaluate and apply the scaling plan. For example, see <a href="https://github.com/kubernetes/autoscaler/issues/5465" target="_blank" rel="noreferrer">Issue#5465</a> where it is highlighted that CA wanted to bring down node count for NodeGroups that had long unregistered and not ready nodes.</li></ul><h5 id="impedence-mismatch-between-ca-and-kube-scheduler" tabindex="-1">Impedence mismatch between CA and kube-scheduler <a class="header-anchor" href="#impedence-mismatch-between-ca-and-kube-scheduler" aria-label="Permalink to &quot;Impedence mismatch between CA and kube-scheduler&quot;">​</a></h5><ul><li>CA does not honor <code>preferredDuringSchedulingIgnoredDuringExecution</code> see <a href="https://github.com/kubernetes/autoscaler/blob/master/cluster-autoscaler/FAQ.md#does-ca-respect-node-affinity-when-selecting-node-groups-to-scale-up" target="_blank" rel="noreferrer">here</a>. As a consequence it results in sub-optimal choice of NodeGroups to be scaled.</li><li><em>Canary-Issue#4276</em> highlights the issue where the CA fitment check differs from the kube-scheduler&#39;s decision of treating a pod as unschedulable. These sort of issues will keep coming as long as CA continues to use only filter plugins from the scheduler and not an actual upstream kube-scheduler. This also will create further problems when the actual kube-scheduler is built with custom scheduler plugins causing the decisions to diverge even further between CA and kube-scheduler.</li><li>Since Kubernetes release 1.18, kube-scheduler supports cluster-wide default PodTopologySpreadConstraints. See <a href="https://kubernetes.io/docs/concepts/scheduling-eviction/topology-spread-constraints/#cluster-level-default-constraints" target="_blank" rel="noreferrer">here</a>. This is done during the <code>Scoring</code> phase of the scheduler and since CA only uses <code>Filtering</code> phase via scheduler APIs, CA can never support it. See <a href="https://github.com/kubernetes/autoscaler/issues/3879" target="_blank" rel="noreferrer">Issue#3879</a>.</li></ul><blockquote><p>Kubernetes kube-scheduler will keep on evolving as new usage patterns emerge in the kubernetes space. It is evident that solutions that do not leverage kube-scheduler as-is will always fall behind which will lead to sub-optimal and sometimes inaccurate scaling advice.</p></blockquote><h5 id="inefficient-scaling-of-nodegroup-s" tabindex="-1">Inefficient scaling of NodeGroup(s) <a class="header-anchor" href="#inefficient-scaling-of-nodegroup-s" aria-label="Permalink to &quot;Inefficient scaling of NodeGroup(s)&quot;">​</a></h5><ul><li>CA is designed to prioritize scale-out over scale-in. This causes issues for consumers who run into resource exhaustion issues during rolling updates. For these consumers scale-in needs to be prioritized over scale-out. Currently a <a href="https://pages.github.tools.sap/kubernetes/gardener/docs/faq/sap-internal/ca-mcm-faqs/#i-want-to-rollout-the-nodes-myself-by-moving-pods-from-one-worker-pool-to-another-worker-pool-during-the-maintenance-time-window-is-there-a-way" target="_blank" rel="noreferrer">hack</a> is suggested which forces consumers to set <code>scale-down-unneeded-time</code> to an aggressive value of <code>0</code> while the rolling updates is ongoing only to be reset post the update is completed. We have already seen multiple occurrences of problems where consumers persist with this aggressive <code>scale-down-unneeded-time</code> value which causes flapping of nodes. This issues is exacerbated due to startup taints added for node critical components, thus making the node unavailable to scheduling of pods.</li><li>When selecting NodeGroup(s) to scale, it employs a very simplistic node scoring by computing wasted resources. There are several issues with the selection criteria: <ul><li>Only CPU and memory are used to compute resource wastage (GPUs etc. are not considered).</li><li>CPU and Memory are treated with the same weightage even though their costs are not proportional.</li><li>Generation of CPU which significantly changes the cost of the instance is not considered.</li><li>Any special requirements like accelerated networking is not taken into account.</li><li>It prefers to max-out a single NodeGroup at a time. This results in imbalance in the distribution of nodes across availability zones. See <a href="https://sap-ti.slack.com/archives/C0170QTBJUW/p1737049671461969" target="_blank" rel="noreferrer">gardener-mcm slack conversation on a recent issue</a>.</li></ul></li><li>CA scaling decisions are agnostic to operational procedures such as rolling updates done outside CA. As a safety mechanism we disable scale-in during upgrades in order to prevent CA from unilaterally changing the replicas for a MachineDeployment.</li><li>CA can overprovision nodes only to reduce it at a later time. It uses <a href="https://en.wikipedia.org/wiki/First-fit-decreasing_bin_packing" target="_blank" rel="noreferrer">First Fit Decreasing Bin-Packing</a> algorithm to estimate the number of new nodes that are required to fit unschedulable pods. See <a href="https://github.com/kubernetes/autoscaler/blob/master/cluster-autoscaler/estimator/binpacking_estimator.go#L91" target="_blank" rel="noreferrer">here</a>. This causes transient increase in the number of potentially underutilized nodes. If the <code>scale-down-unneeded-time</code> and <code>scale-down-utilization-threshold</code> is configured with higher values then the amount of time for which overprovisioned nodes will not be removed increases thus increasing the overall cost.</li></ul><h4 id="scalability-challenges" tabindex="-1">Scalability challenges <a class="header-anchor" href="#scalability-challenges" aria-label="Permalink to &quot;Scalability challenges&quot;">​</a></h4><ul><li>The last known scalability evaluation is available <a href="https://github.com/kubernetes/autoscaler/blob/master/cluster-autoscaler/proposals/scalability_tests.md" target="_blank" rel="noreferrer">here</a>. The actual performance of CA does not match the expected performance. This was further highlighted in <a href="https://github.com/kubernetes/autoscaler/issues/5769" target="_blank" rel="noreferrer">Issue#5769</a> which has been closed without a resolution. With increase in pods/nodes the amount of time it takes for scaling to complete increases exponentially. Recently <a href="https://github.com/kubernetes/autoscaler/blob/master/cluster-autoscaler/proposals/provisioning-request.md" target="_blank" rel="noreferrer">ProvisioningRequest</a> custom resource has been introduced. One of the goals is to reduce the end-to-end scale-out latency. However neither the proposal nor any other document presents benchmarking numbers to back their claims. <ul><li>We confirmed the CA (v1.29) scalability issue by testing it locally. For 4.5K pods and around 400 nodes, the total approximate time to compute the scale-out plan was around 15mins.</li></ul></li></ul><h4 id="maintenance-challenges" tabindex="-1">Maintenance challenges <a class="header-anchor" href="#maintenance-challenges" aria-label="Permalink to &quot;Maintenance challenges&quot;">​</a></h4><ul><li>In Gardener a fork of the upstream Cluster Autoscaler is maintained. This entails investing regular effort in doing the following: <ul><li>Rebasing at every release of upstream CA. If breaking changes are introduced then it takes significant time to analyse the impact of the changes to MCM CloudProvider implementation.</li><li>To minimise the 2-actor problems between CA and MCM, core CA code has been adapted/changed/commented. With every rebase care needs to be taken to ensure that modified code continues to work.</li><li>The overall size of the CA repository is over 200Mb which includes the code from multiple cloud provider implementations that is not consumed in Gardener. As a consequence local setup and development is resource heavy and slow.</li></ul></li></ul><h5 id="diagnostic-challenges" tabindex="-1">Diagnostic challenges <a class="header-anchor" href="#diagnostic-challenges" aria-label="Permalink to &quot;Diagnostic challenges&quot;">​</a></h5><ul><li>Pod triggered scaled up events emitted by the CA are inaccurate since all the pods that were involved in the scale-out evaluation were logged as part of this triggered-scale-up-event. This set of pods is not neccessarily the set of pods that caused the actual scale up. This makes diagnostics trickier and developers needs to be trained to ignore these logs and only look at the final scale-out plan.</li><li>CA does not emit logs at the right log-level for critical failure in scaling-out NodeGroups. This forces the operators to change the log level to DEBUG to get this information which in turn results in an overload of logs.</li></ul><h2 id="way-forward" tabindex="-1">Way forward <a class="header-anchor" href="#way-forward" aria-label="Permalink to &quot;Way forward&quot;">​</a></h2><h3 id="alternatives-evaluated" tabindex="-1">Alternatives evaluated <a class="header-anchor" href="#alternatives-evaluated" aria-label="Permalink to &quot;Alternatives evaluated&quot;">​</a></h3><p>Currently there are only <a href="https://kubernetes.io/docs/concepts/cluster-administration/node-autoscaling/#autoscaler-implementations" target="_blank" rel="noreferrer">two cluster autoscaling implementations</a> that are currently sponsored by SIG autoscaling - <a href="https://github.com/kubernetes/autoscaler/tree/master/cluster-autoscaler" target="_blank" rel="noreferrer">Cluster Autoscaler (CA)</a> and <a href="https://github.com/kubernetes-sigs/karpenter" target="_blank" rel="noreferrer">Karpenter</a>. Gardener already uses CA, which leaves us with only one alternative. We evaluated Karpenter and observed the following:</p><ul><li>It suffers from the same issue as CA w.r.t differing from decisions made by the kube-scheduler. The CA leverages kube-scheduler filter plugins to select nodes for unschedulable pods but Karpenter does not leverage any API from kube-scheduler.</li><li>It offers a more elaborate consolidation as compared to CA. However, active consolidation is seldom turned on due to potential disruptions to the deployed workloads. Even though Karpenter offers <a href="https://karpenter.sh/docs/concepts/disruption/" target="_blank" rel="noreferrer">disruption budget</a> it still is not a heavily used feature and there are open issues on this feature.</li><li>It offers general lifecycle management of instances/machines apart from autoscaling clusters. This creates a larger overlap of responsibilities with node-lifecycle-management components like the MCM thus aggravating the two-actor issues.</li><li>It only supports <a href="https://github.com/aws/karpenter-provider-aws" target="_blank" rel="noreferrer">AWS</a> and <a href="https://github.com/Azure/karpenter-provider-azure" target="_blank" rel="noreferrer">Azure</a> cloud providers at the moment.</li><li>It couples scaling advice with node lifecycle actions thus changes in core advisor logic will require a fork to be maintained or contribute upstream.</li></ul><h3 id="how-we-addressed-ca-challenges" tabindex="-1">How we addressed CA challenges? <a class="header-anchor" href="#how-we-addressed-ca-challenges" aria-label="Permalink to &quot;How we addressed CA challenges?&quot;">​</a></h3><p>A proof-of-concept <a href="https://github.tools.sap/kubernetes/gardener-scaling-recommender" target="_blank" rel="noreferrer">Scaling Advisor</a> was envisaged which has single responsibility to provide scaling advice by leveraging the kubernetes kube-scheduler on the current cluster state.</p><p><img src="'+a+'" alt="Scaling Advisor POC Flow"></p><h4 id="single-actor-responsibility" tabindex="-1">Single actor responsibility <a class="header-anchor" href="#single-actor-responsibility" aria-label="Permalink to &quot;Single actor responsibility&quot;">​</a></h4><p>Scaling analysis should be the primary concern of a scaling advisor. In our PoC, a clear separation was introduced between the responsibilities of scaling analysis and scaling execution. Our scaling-advisor provides scaling advice after analysis of the as-is cluster state which includes the unscheduled pods. Since lifecycle-management components like MCM will leverage the advice produced by the scaling-advisor and will be the only actor to perform real lifecycle operations on the cluster, there are no overlapping actors.</p><h4 id="alleviating-ca-inherent-design-flaws" tabindex="-1">Alleviating CA inherent design flaws <a class="header-anchor" href="#alleviating-ca-inherent-design-flaws" aria-label="Permalink to &quot;Alleviating CA inherent design flaws&quot;">​</a></h4><ul><li><p>Due to clear separation of responsibilities, we have the following advantages:</p><ul><li>Concurrency issues (if any) in the scaling-advisor will not propagate to the lifecycle management component like MCM.</li><li>There will be no overlap/conflict of tuning parameters between the scaling-advisor and the lifecycle management component.</li><li>Simplifies the code base as there is no provider-specific implementation in the scaling advice.</li></ul></li><li><p>Leverages a real kube-scheduler running as part of a virtual cluster to run simulations and provide scaling advice.</p><ul><li>This removes any possibility of deviating from the actual kube-scheduler (default or custom) decisions.</li><li>Minimises the possibility of over provisioning nodes that CA suffers from.</li><li>In the absence of explicit instance priority, scaling advice also respects <code>preferredDuringSchedulingIgnoredDuringExecution</code> and chooses cost-optimised instance types that statisfy the unschedulable pod requirements more closely.</li><li>Automatically supports <a href="https://kubernetes.io/docs/concepts/scheduling-eviction/topology-spread-constraints/#cluster-level-default-constraints" target="_blank" rel="noreferrer">cluster wide default scheduling constraints</a>.</li></ul></li><li><p>The lifecycle management component controls the execution of the scaling advice. This differs from the current hard coded prioritization in CA where scale-outs are always prioritized over scale-ins.</p></li><li><p>scaling-advisor attempts to minimize the overall <em>price</em> of scaled-out resources. CPU and memory are treated differentially in the computation of waste for evaluating the node score. This was achieved by pre-computing the relevant cost ratios for the given cloud provider and region.</p><blockquote><p>NOTE: As part of the POC only CPU and Memory were considered for scoring nodes. However during productization this can be further improved.</p></blockquote></li><li><p>scaling-advisor does a better job balancing scale-outs across availability zones. In a single simulation run it takes a cross product of single instance type and multiple zones and takes the best score.</p></li></ul><h4 id="scalability" tabindex="-1">Scalability <a class="header-anchor" href="#scalability" aria-label="Permalink to &quot;Scalability&quot;">​</a></h4><p>Anectodally we observed that scaling advisor POC was faster than CA in computing scaling plan for large clusters like HANA. However, we are yet to carry out rigorous benchmarking which will be done during productization.</p><h3 id="proof-of-concept-validation" tabindex="-1">Proof of concept validation <a class="header-anchor" href="#proof-of-concept-validation" aria-label="Permalink to &quot;Proof of concept validation&quot;">​</a></h3><ul><li>Captured scaling relevant cluster state (nodes, pods...) for several clusters on Canary and Live landscapes using a specially developed <em>Scaling history recorder</em>.</li><li>The data captured by <code>Scaling History recorder</code> was <em>replayed</em> against both the <em>Virtual Cluster Autoscaler</em>and the <em>Scaling Recommender POC</em> and the results were compared to auto-generate comparison reports.</li></ul><h3 id="envisaged-value-differentiators" tabindex="-1">Envisaged value differentiators <a class="header-anchor" href="#envisaged-value-differentiators" aria-label="Permalink to &quot;Envisaged value differentiators&quot;">​</a></h3><ul><li>Capability to plug-and-play kube-scheduler for affecting scaling advice.</li><li>Capability to provide native support for gang-scheduled pods.</li><li>Capability to adapt to flexible worker pool configurations.</li></ul><h3 id="risk-mitigation" tabindex="-1">Risk Mitigation <a class="header-anchor" href="#risk-mitigation" aria-label="Permalink to &quot;Risk Mitigation&quot;">​</a></h3><ul><li>We will continue to support CA for forseeable future.</li><li>Functionalities of CA that are consumed by our stakeholders will be supported by the scaling-advisor and MCM which will enable easy transition from CA to scaling-advisor for existing shoots.</li><li>A feature flag will be introduced to switch to using the scaling-advisor for any shoot cluster to permit the stakeholder to verify the behavior of the new component for real-life workloads.</li></ul><h3 id="non-goal" tabindex="-1">Non Goal <a class="header-anchor" href="#non-goal" aria-label="Permalink to &quot;Non Goal&quot;">​</a></h3><ul><li>scaling-advisor is independent of the Cluster API. Any VM lifecycle management component can leverage this as a library.</li><li>scaling-advisor will not revise the Gardener worker pool concept.</li></ul><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><ul><li>One of the CA comitters explains why CA can differ from the decisions taken by the kube-scheduler and why CA does not support soft constraints. See <a href="https://vadasambar.com/post/kubernetes/would-ca-consider-my-soft-constraints/" target="_blank" rel="noreferrer">article</a>.</li></ul>',48)]))}const m=t(s,[["render",n]]);export{f as __pageData,m as default};
